import sys, json, itertools
from decimal import Decimal, ROUND_HALF_UP, getcontext
sys.path.insert(0, '/var/tmp/foundry-work/scripts-r0')
from rows import ROWS
getcontext().prec = 60

NICK = {'bob':'robert','bill':'william','will':'william','liz':'elizabeth','beth':'elizabeth','peggy':'margaret','maggie':'margaret','jim':'james','jimmy':'james','rick':'richard','dick':'richard','kate':'katherine','kathy':'katherine','jen':'jennifer','jenny':'jennifer','mike':'michael','tom':'thomas','trish':'patricia','patty':'patricia','chris':'christopher','dan':'daniel','danny':'daniel','sue':'susan','suzy':'susan','ted':'edward','ned':'edward','tony':'anthony','becky':'rebecca','vicky':'victoria','nate':'nathaniel','abby':'abigail','theo':'theodore','gwen':'gwendolyn','hattie':'harriet','hannes':'johannes','fritz':'friedrich','sepp':'josef','steffi':'stefanie','kathi':'katharina','matze':'matthias','wolfi':'wolfgang','gisi':'gisela','pepe':'josé','paco':'francisco','nacho':'ignacio','lola':'dolores','concha':'concepción','beppe':'giuseppe','gianni':'giovanni','mimmo':'domenico','lello':'raffaele','piet':'pieter','bram':'abraham','kris':'kristoffer'}
ACC = {'ä':['a','ae'],'ö':['o','oe'],'ü':['u','ue'],'ß':['ss'],'ø':['o','oe'],'å':['a','aa'],'æ':['ae'],'ō':['o','ou'],'ū':['u','uu'],
       'é':['e'],'è':['e'],'ê':['e'],'ë':['e'],'á':['a'],'à':['a'],'â':['a'],'ã':['a'],'í':['i'],'î':['i'],'ï':['i'],'ó':['o'],'ò':['o'],'ô':['o'],'ú':['u'],'ñ':['n'],'ç':['c'],'ā':['a']}

def variants(s):
    s = s.lower().replace("'", "").replace(".", "").replace(" ", "").replace("-", "")
    out = {''}
    for ch in s:
        opts = ACC.get(ch, [ch])
        out = {o + x for o in out for x in opts}
    return out

def has_accent(s):
    return any(ch in ACC for ch in s.lower())

def dl(a, b):  # optimal string alignment distance
    d = [[0]*(len(b)+1) for _ in range(len(a)+1)]
    for i in range(len(a)+1): d[i][0] = i
    for j in range(len(b)+1): d[0][j] = j
    for i in range(1, len(a)+1):
        for j in range(1, len(b)+1):
            c = 0 if a[i-1] == b[j-1] else 1
            d[i][j] = min(d[i-1][j]+1, d[i][j-1]+1, d[i-1][j-1]+c)
            if i > 1 and j > 1 and a[i-1] == b[j-2] and a[i-2] == b[j-1]:
                d[i][j] = min(d[i][j], d[i-2][j-2]+1)
    return d[len(a)][len(b)]

def formal(given):
    g = given.lower()
    return NICK.get(g, g)

def part_dist(a, b):
    return min(dl(x, y) for x in variants(a) for y in variants(b))

def names_match(r1, r2):
    g = part_dist(formal(r1['given']), formal(r2['given']))
    f = part_dist(r1['family'], r2['family'])
    return g + f <= 1

class R(dict): pass
recs = []
for t in ROWS:
    keys = ['id','sys','given','family','dob','country','phone','bal','ccy','upd']
    r = R(zip(keys, t))
    recs.append(r)

def dob_ok(r): return r['dob']
parent = {r['id']: r['id'] for r in recs}
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]; x = parent[x]
    return x
def union(a, b): parent[find(a)] = find(b)

pairs = []
for a, b in itertools.combinations(recs, 2):
    if not names_match(a, b):
        continue
    if a['dob'] and b['dob']:
        if a['dob'] == b['dob']:
            union(a['id'], b['id']); pairs.append(('3a', a['id'], b['id']))
    elif a['phone'] and b['phone'] and a['phone'] == b['phone']:
        union(a['id'], b['id']); pairs.append(('3b', a['id'], b['id']))

groups = {}
for r in recs:
    groups.setdefault(find(r['id']), []).append(r)

def date_key(r): return r['upd']
def order(rows):
    return sorted(rows, key=lambda r: (r['sys'] == 'BRIGHTDESK', tuple(-ord(c) for c in r['upd'])))

RATE = {  # units of QUOTE per 1 unit BASE (USD-based rates inverted below)
 'EUR': ('mul', Decimal('1.1097')), 'GBP': ('mul', Decimal('1.3149')),
 'JPY': ('div', Decimal('146.4918')), 'CHF': ('div', Decimal('0.8735')),
 'CAD': ('div', Decimal('1.3294')), 'DKK': ('div', Decimal('6.9559')),
 'MXN': ('div', Decimal('16.7081')), 'USD': None,
}
def to_usd(amount, ccy):
    if ccy == 'USD': return amount
    op, rate = RATE[ccy]
    v = amount * rate if op == 'mul' else amount / rate
    return v.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

def master_balance(r):
    if r['bal'] is None: return None
    v = Decimal(r['bal'])
    if r['sys'] in ('LEDGR', 'KOBO'):   # sign changes in the master
        v = -v
    return v

def title(s):
    return s.capitalize() if s.isupper() else s

def restore_accent(part, others):
    if has_accent(part): return part
    for o in others:
        if has_accent(o) and part.lower() in variants(o) and formal(part) == formal(o) or (has_accent(o) and part.lower() in variants(o)):
            return o
    return part

out = []
for root, rows in groups.items():
    ro = order(rows)
    ids = sorted(r['id'] for r in rows)
    # names
    first = ro[0]
    given = formal(first['given']).title() if formal(first['given']) != first['given'].lower() or first['given'].lower() in NICK else title(first['given'])
    family = title(first['family'])
    gcands = [r['given'] for r in ro[1:]]
    fcands = [r['family'] for r in ro[1:]]
    if not has_accent(given):
        given = next((c for c in [formal(c).title() if formal(c) else c for c in gcands] if has_accent(c) and given.lower() in variants(c)), given)
    if not has_accent(family):
        family = next((c for c in fcands if has_accent(c) and family.lower() in variants(c)), family)
    # birth date
    dobs = {r['dob'] for r in rows if r['dob']}
    assert len(dobs) <= 1, (ids, dobs)
    dob = dobs.pop() if dobs else None
    # country, phone, amount from most recent row that supplies each
    country = next((r['country'] for r in ro if r['country']), None)
    phone = next((r['phone'] for r in ro if r['phone']), None)
    amt = None
    for r in ro:
        mv = master_balance(r)
        if mv is not None:
            amt = to_usd(mv, r['ccy']); break
    out.append({'entity_id': ids[0], 'source_rows': ids,
                'given_name': given, 'family_name': family,
                'birth_date': dob, 'country': country, 'phone_e164': phone,
                'amount_usd': float(amt) if amt is not None else None,
                '_order': [r['id'] for r in ro]})

out.sort(key=lambda x: x['entity_id'])
for o in out:
    print(o['entity_id'], o['source_rows'], o['given_name'], o['family_name'], o['birth_date'], o['country'], o['phone_e164'], o['amount_usd'], o['_order'])
print('persons', len(out), 'rows', sum(len(o['source_rows']) for o in out))
json.dump(out, open('/var/tmp/foundry-work/scripts-r0/out_debug.json', 'w'), ensure_ascii=False, indent=1)

